def count_substring_occurrences(input_string, substring):
    if not input_string or not substring:
        return "Both the string and substring must not be empty"

    count = 0
    for i in range(len(input_string) - len(substring) + 1):
        if input_string[i:i + len(substring)] == substring:
            count += 1

    return count

